import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes2')
from h import *
X=[]
X.append(r(9668816,"Curry tailandés en Instant Pot","¡Un curry tailandés casero, fácil, en una sola olla, lleno de capas de increíbles sabores! Es nutritivo y saludable, ¡pero sabe a comida reconfortante!","5 porciones","1 porción",
["1 cucharada de aceite de coco, omita para una versión sin aceite y saltee en agua o caldo","1 cebolla amarilla grande picada finamente","6 dientes de ajo pelados y picados finamente","1 cucharada de jengibre fresco rallado o picado finamente (aprox. 1\" de raíz de jengibre)","2 pimientos rojos en rodajas (o del color de su elección)","2 zanahorias grandes cortadas en tiras","1 cabeza de brócoli cortada en floretes","1 taza de caldo de verduras bajo en sodio","1 lata de 400 ml de leche de coco sin azúcar Thai Kitchen *puede usar light para menos grasa, pero también tendrá menos sabor a coco","5 cucharadas de pasta de curry rojo Thai Kitchen","2 cucharadas de tamari o salsa de soya si no evita el gluten","1 cucharada de jarabe de arce","½ cucharadita de pimienta negra","2 cucharadas de jugo de limón, aprox. 1 limón grande",("Opcional","Sirva con arroz integral o blanco, fideos o pan naan."),("Opcional","Decore con rodajas de limón, albahaca tailandesa, cilantro y/o sriracha, si lo desea.")],
["Prepare y pique todas las verduras antes de comenzar. Luego programe su Instant Pot en la función de saltear, agregue el aceite de coco (si lo usa) y la cebolla picada, y saltee de 3 a 5 minutos, revolviendo con frecuencia. Luego agregue el jengibre y el ajo picados/rallados a la olla, mezcle bien y saltee unos 30 segundos más.","Apague la olla y agregue todos los demás ingredientes EXCEPTO el jugo de limón. Mezcle bien, cierre la tapa y coloque la válvula en la posición de sellado. Programe su olla en manual o cocción a presión (según su modelo) durante 3 minutos a alta presión. Tardará unos 10 minutos en alcanzar la presión y luego comenzará la cuenta regresiva.","Cuando termine, libere el vapor rápidamente con la válvula y abra la tapa cuando sea seguro hacerlo. Exprima el jugo de limón en la olla y mezcle bien. Sirva con arroz, fideos o pan naan y decore con sriracha y hierbas frescas, si lo desea."],
["Dé a su curry tailandés un impulso de proteína agregando una lata de garbanzos o lentejas, si lo desea. Para más picante, agregue media cucharadita de pimienta de cayena u hojuelas de chile. Este plato me parece solo ligeramente picante tal como está. Use jengibre y ajo FRESCOS para obtener los mejores resultados de sabor. Si sigue una dieta baja en grasa, puede omitir el aceite de coco y saltear en caldo de verduras o agua. También puede sustituir la leche de coco por una versión light; sin embargo, tenga en cuenta que tendrá un poco menos de sabor a coco. Para una versión sin soya, omita el tamari o la salsa de soya y agregue un poco más de sal en su lugar. O sustituya por aminos de coco. ¿No tiene brócoli? Sustitúyalo por guisantes dulces (snap peas), ejotes (judías verdes), coliflor o col rizada (kale). Guarde el arroz y el curry tailandés sobrantes en recipientes separados en el refrigerador hasta por 3 días. Recaliente y disfrute."],[]))
X.append(r(9671588,"Ensalada de pasta con pesto de lentejas","¡Una ensalada de pasta con lentejas y pesto de lentejas! Es sabrosa, sencilla de preparar y queda fantástica tibia o fría.","4 porciones","1 porción",
[("Para el pesto de lentejas","1 taza de hojas de albahaca fresca, compactadas"),("Para el pesto de lentejas","½ taza de lentejas verdes, cocidas o enlatadas"),("Para el pesto de lentejas","2 dientes de ajo pelados"),("Para el pesto de lentejas","2 cucharadas de jugo de limón, aprox. medio limón"),("Para el pesto de lentejas","2-3 cucharadas de caldo de verduras"),("Para el pesto de lentejas","sal + pimienta al gusto"),("Para la ensalada de pasta con lentejas","½ libra de pasta rotini u otra pasta corta"),("Para la ensalada de pasta con lentejas","1 pinta de tomates cherry cortados por la mitad"),("Para la ensalada de pasta con lentejas","½ taza de lentejas verdes, cocidas o enlatadas"),("Para la ensalada de pasta con lentejas","½ taza de almendras en tiras, tostadas")],
["Lleve a ebullición una olla grande con agua generosamente salada y cocine la pasta según las instrucciones del paquete para pasta 'al dente'. Escurra (PERO reserve 1/2 taza del agua de la pasta), pásela a un tazón grande y reserve.","Mientras tanto, agregue todos los ingredientes del pesto de lentejas, excepto el caldo, al procesador de alimentos y procese hasta que esté finamente picado, raspando los lados según sea necesario. Luego agregue 2-3 cucharadas del caldo para aligerar el pesto a su gusto. Pruebe la sal y la pimienta y agregue un poco si es necesario.","Ahora agregue el pesto, la otra 1/2 taza de lentejas, los tomates cherry y las almendras en tiras (reservando algunas para decorar) al tazón con la pasta cocida. Mezcle bien y agregue un poco del agua de la pasta reservada si es necesario. Sirva tibia o fría."],
["Ponga sal al agua de la pasta. Asegúrese de agregar suficiente sal a la olla de agua para obtener la mejor textura y sabor. Aquí hay una guía práctica para ayudarle a salar el agua perfectamente cada vez.","Cocine la pasta 'al dente'. La pasta al dente suele estar de 1 a 3 minutos \"poco cocida\". Así es como los italianos comen su pasta. 😉 Nos gusta un poco de firmeza, y nada de pasta blanda.","La ensalada de pasta con lentejas sobrante se conserva refrigerada de 3 a 4 días. No recomiendo congelarla."],[]))
X.append(r(9675054,"Ensalada vegana de elote [sin aceite + ¡MUY fácil!]","Transformamos un clásico mexicano en una ensalada vegana de elote rica, sabrosa, cremosa e increíblemente deliciosa. Seguro que agradará a todos.","4 porciones","1 porción",
["2 tazas de maíz congelado, descongelado","1 taza de pepino picado en cubos","1 aguacate mediano picado en cubos","¼ de taza de cebolla morada picada en cubos","⅓ de taza de hojas de cilantro","½ cucharadita de hojuelas de chile o más",("Para el aderezo","½ taza de nueces de la India (anacardos) crudas"),("Para el aderezo","2 cucharadas de jugo de limón, aprox. la mitad de un limón mediano"),("Para el aderezo","¼ de taza de agua fresca"),("Para el aderezo","1 cucharada de vinagre de manzana"),("Para el aderezo","¼ de cucharadita de sal marina o al gusto"),("Decoraciones opcionales","más cilantro"),("Decoraciones opcionales","queso parmesano vegano"),("Decoraciones opcionales","más hojuelas de chile")],
["Agregue todos los ingredientes del aderezo a su licuadora y procese hasta que quede suave y cremoso. Comience a velocidad baja y luego aumente lentamente para evitar que salpiquen trocitos de nuez de la India. Raspe los lados según sea necesario. Reserve.","Combine todos los ingredientes de la ensalada en un tazón para mezclar, vierta el aderezo encima y mezcle bien.","Refrigere durante 1 hora o sirva de inmediato."],
["Si no tiene una licuadora potente, remoje previamente las nueces de la India. Puede remojarlas toda la noche en agua fría, o remojarlas en agua hirviendo durante 30 minutos. El tiempo de remojo las hinchará y ablandará, haciéndolas más fáciles de licuar. Aunque puede disfrutarla de inmediato, este elote vegano sabe mejor frío después de 1 hora, así que planifique con anticipación si es posible. Para menos picante, reduzca a la mitad las hojuelas de chile, o sustitúyalas por chile en polvo. Si no tiene limón, puede sustituir por jugo de lima o usar más vinagre. Las sobras se conservan refrigeradas de 3 a 4 días."],[]))
X.append(r(9682858,"Dip vegano estilo ranch [sin aceite + opción sin nueces]","Aprenda a preparar este dip vegano estilo ranch fácil con ingredientes de la despensa y una licuadora. Solo necesita 5 minutos para este cremoso y delicioso dip ranch de nuez de la India con el que querrá mojar de todo.","8 porciones","1 porción",
["1 taza de nueces de la India (anacardos) crudas","½ taza de agua, más 1-2 cucharadas si lo prefiere más líquido","1 cucharada de jugo de limón","1 cucharadita de perejil seco","1 cucharadita de eneldo seco","½ cucharadita de ajo en polvo","½ cucharadita de sal marina","¼ de cucharadita de pimienta negra"],
["Agregue todos los ingredientes a una licuadora de alta velocidad y procese hasta que quede suave.","Pase a un tazón o recipiente y refrigere durante 1 hora antes de servir."],
["Si no tiene una licuadora potente, remoje las nueces de la India en agua hirviendo de 20 a 30 minutos. Luego escúrralas antes de licuar. Para aderezo ranch, agregue de 1 a 3 cucharadas adicionales de agua para aligerarlo a su gusto. O agregue de 1 a 3 cucharadas de vinagre de manzana. Una vez licuado, pruebe y agregue más sal u otros condimentos, si lo prefiere. Guarde refrigerado en un recipiente sellado hasta por 7 días, o congele en un recipiente hermético hasta por 6 meses. La información nutricional corresponde a aprox. 2 cucharadas o ⅛ del dip."],[]))
X.append(r(9685307,"Galletas veganas de avena y mantequilla de maní","¡Galletas veganas de avena y mantequilla de maní masticables e irresistibles! Son dulces, pero saludables, para la galleta de desayuno perfecta.","10 galletas","1 porción",
["½ taza de mantequilla de maní cremosa","⅓ de taza de jarabe de arce","¼ de taza de leche sin lácteos","1.5 tazas de avena en hojuelas","100 gramos (aprox. 1 taza) de harina de almendra blanqueada","½ cucharadita de bicarbonato de sodio","⅓ de taza de chispas de chocolate oscuro, opcional"],
["Precaliente el horno a 350℉/176℃ y forre una bandeja para hornear con papel pergamino.","Combine la mantequilla de maní, el jarabe de arce y la leche en un tazón mediano y mezcle bien. Luego agregue la avena, la harina de almendra y el bicarbonato de sodio y mezcle hasta combinar. Si usa las chispas de chocolate, incorpórelas a continuación.","Para galletas grandes (como en la foto) use una cuchara para galletas de dos cucharadas. Forme 10 bolitas con la mezcla y colóquelas en la bandeja para hornear con bastante espacio entre cada una. Presione suavemente cada una con el reverso de una cuchara para ayudarlas a extenderse. (Seguirán extendiéndose en el horno.)","Luego hornee las galletas de 11 a 12 minutos y retire la bandeja del horno. Las galletas pueden parecer poco cocidas, pero se pondrán firmes al enfriarse. Déjelas reposar 10 minutos, luego disfrútelas tibias, o páselas a una rejilla para que sigan enfriándose."],
["Hice las galletas muy grandes para que sean una galleta de desayuno. Sin embargo, puede obtener fácilmente 20 galletas si usa una cuchara para galletas más pequeña (de 1 cucharada). Esto reducirá a la mitad la información nutricional por galleta.","Pese la harina de almendra para obtener los resultados más exactos, en lugar de depender de las medidas en tazas.","Deje bastante espacio entre cada galleta, ya que se extenderán bastante.","Las galletas parecerán poco cocidas, pero se pondrán firmes a temperatura ambiente, así que no las hornee de más."],[]))
X.append(r(9688344,"Pan de maíz vegano sin aceite","¡Pan de maíz vegano sin aceite increíblemente sencillo y delicioso!","16","1 porción",
[("Ingredientes húmedos","1 taza de leche de soya o la leche vegetal de su elección"),("Ingredientes húmedos","1 cucharada de vinagre de manzana"),("Ingredientes húmedos","⅓ de taza de puré de manzana sin azúcar"),("Ingredientes húmedos","¼ de taza de jarabe de arce"),("Ingredientes secos","160 gramos de harina de maíz molida fina o mediana (aprox. 1 taza)"),("Ingredientes secos","150 gramos de harina integral para repostería, aprox. 1 ¼ tazas"),("Ingredientes secos","1 cucharada de polvo para hornear"),("Ingredientes secos","1 cucharadita de sal marina")],
["Precaliente el horno a 400℉/204℃ y forre un molde cuadrado para hornear de 9\"x9\" con papel pergamino.","Coloque la leche de soya y el vinagre de manzana en un tazón pequeño y reserve unos minutos hasta que espese y se cuaje.","Mientras tanto, agregue todos los ingredientes secos a un tazón para mezclar y bata para combinar. Luego agregue la leche cuajada con los demás ingredientes húmedos al mismo tazón y revuelva hasta combinar, sin mezclar de más.","Vierta la masa en el molde preparado y hornee de 15 a 18 minutos, o hasta que un palillo insertado en el centro salga limpio.","Retire del horno y deje enfriar de 5 a 10 minutos antes de cortar."],
["Si usa un molde de otro tamaño, el tiempo de horneado variará. Por ejemplo: un molde de 8″x8″ requerirá unos minutos adicionales. Siempre verifique con un palillo para asegurarse del punto de cocción.","¡Use harina de maíz (cornmeal), NO maicena! No son lo mismo. La maicena es SOLO el almidón con todo lo demás eliminado. Puede encontrar harina de maíz (cornmeal) en la sección de harinas de su supermercado.","Para una textura óptima, use harina de maíz molida fina o mediana, no gruesa, a menos que disfrute de una textura arenosa.","Use polvo para hornear ACTIVO para obtener los mejores resultados. El polvo para hornear que lleva abierto en la despensa más de 6 meses puede empezar a perder su efectividad.","Forre el molde con papel pergamino para pasarlo más fácilmente una vez horneado. Sujete ambos lados del papel y levante el pan para pasarlo a una tabla de cortar o una rejilla, para que se enfríe más rápido.","No mezcle demasiado la masa. Puede ser tentador seguir mezclando hasta que la masa quede perfectamente suave. Pero unos cuantos grumos están perfectamente bien. Mezclar de más puede dar como resultado una textura seca y/o gomosa.","Sabe mejor recién hecho o dentro de 1-2 días. Las sobras se conservan a temperatura ambiente de 3 a 4 días, cubiertas con un paño limpio y seco, o en un recipiente sellado. O congélelas en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9689734,"Cómo hacer mantequilla de nuez de la India (anacardo)","¡Es espesa, rica y perfectamente suave! Aprenda a preparar mantequilla de nuez de la India en casa con solo 1 ingrediente.","20 porciones de 1 cucharada","1 porción",
["3 tazas de nueces de la India (anacardos) crudas",("Complementos opcionales (elija ninguno, algunos o todos)","1 cucharada de jarabe de arce"),("Complementos opcionales (elija ninguno, algunos o todos)","1 cucharada de aceite de aguacate u otro aceite de sabor neutro"),("Complementos opcionales (elija ninguno, algunos o todos)","1 cucharadita de vainilla"),("Complementos opcionales (elija ninguno, algunos o todos)","1 cucharadita de canela"),("Complementos opcionales (elija ninguno, algunos o todos)","1/16 de cucharadita de sal marina, una pizca")],
["Precaliente el horno a 350 grados y forre una bandeja grande con papel pergamino. Distribuya las nueces de la India en una sola capa y hornee de 5 a 6 minutos. Están listas cuando estén doradas y tibias, pero NO quemadas. Retire del horno.","Agregue las nueces de la India a un procesador de alimentos. Procese a velocidad alta hasta que quede cremosa, deteniéndose con frecuencia para raspar los lados. Las nueces de la India pasarán de enteras, a harina, a grumos y, finalmente, a una cremosa mantequilla de nueces. Tomará varios minutos de procesamiento, entre 5 y 12 minutos con descansos. Dé a su máquina descansos de 30 a 60 segundos, según sea necesario, para evitar el sobrecalentamiento.","OPCIONAL: Una vez que esté completamente suave, agregue los complementos opcionales, si los usa, y pulse un par de veces para combinar.","Pase la mantequilla de nuez de la India a un frasco limpio y seco y úsela como cualquier otra mantequilla de nueces."],
["Dé a su máquina pequeños descansos entre cada procesamiento para evitar que se sobrecaliente. Apague el procesador de alimentos de 30 a 60 segundos cada vez, según sea necesario, y luego continúe. Aproveche ese descanso para raspar los lados. Su mantequilla de nuez de la India casera pasará por muchas etapas y puede parecer que nunca se convertirá en mantequilla, pero lo hará. Pasa de nueces enteras, a trozos pequeños, a harina, a grumos pequeños, luego a grumos grandes y finalmente a una cremosa mantequilla de nueces. (Vea arriba las fotos del proceso para una referencia visual.) Para una versión sin azúcar, omita el jarabe de arce opcional, o si le gusta lo dulce, aumente a dos cucharadas. (Pruebe primero con una.) Puede usar una licuadora de alta velocidad, como una Vitamix, para obtener resultados más rápidos, pero me resulta más fácil retirar la mantequilla de nueces de un procesador de alimentos. Guarde en un recipiente o frasco limpio y seco a temperatura ambiente hasta por 1 semana, o refrigere hasta por 4 semanas. Puede congelarla en un recipiente hermético apto para congelador hasta por 4 meses."],[]))
X.append(r(9690413,"Dip ahumado de lentejas","Un dip de lentejas ahumado y delicioso, sabroso y lleno de proteína.","4 porciones","1 porción",
["⅔ de taza de lentejas rojas partidas, secas","2 tazas de caldo de verduras","3 cucharadas de tahini","2 cucharadas de vinagre de manzana","2 dientes de ajo","1 cucharadita de pimentón ahumado","⅛ de cucharadita de pimienta de cayena","sal + pimienta al gusto"],
["Enjuague y seleccione las lentejas para desechar piedritas o residuos. Luego colóquelas en una olla pequeña con el caldo de verduras. Lleve a ebullición, luego reduzca el fuego y cocine a fuego lento hasta que estén cocidas por completo, aprox. 8 minutos.","Escurra las lentejas, pero reserve el agua de cocción por si la necesita para aligerar el dip de lentejas.","Pase las lentejas cocidas al procesador de alimentos y agregue todos los demás ingredientes. Licúe hasta que estén completamente combinados, agregando 1-2 cucharadas del agua de las lentejas si es necesario para un dip más líquido. (Tenga en cuenta que las lentejas seguirán absorbiendo líquido y el dip espesará al reposar.)","Pruebe la sal y la pimienta y agregue si es necesario. Luego sirva el dip tibio o refrigérelo durante 1 hora o más antes de servir."],
["Cocine las lentejas en caldo de verduras, no en agua, para obtener el mejor sabor. Si no tiene caldo a mano, pruebe a preparar nuestra deliciosa mezcla de caldo concentrado (bouillon).","Si debe usar agua, asegúrese de agregar condimento adicional, al gusto.","Si usa lentejas enlatadas, aumente el condimento para compensar la falta del caldo de verduras.","Guarde las sobras en el refrigerador en un recipiente sellado de 3 a 4 días. O congele el dip en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9692965,"Nueces pecanas en freidora de aire [dos sabores]","¡Nueces pecanas crujientes y adictivas en freidora de aire, en dos deliciosos sabores!","6 porciones","1 porción",
[("Nueces pecanas confitadas en freidora de aire","¼ de taza de azúcar morena o azúcar de coco sin refinar"),("Nueces pecanas confitadas en freidora de aire","½ cucharadita de canela"),("Nueces pecanas confitadas en freidora de aire","2 cucharadas de agua"),("Nueces pecanas confitadas en freidora de aire","1 cucharadita de extracto puro de vainilla"),("Nueces pecanas confitadas en freidora de aire","1.5 tazas de mitades de nuez pecana"),("Nueces pecanas especiadas en freidora de aire","1 cucharada de jarabe de arce o jarabe de dátil o endulzante líquido de su elección"),("Nueces pecanas especiadas en freidora de aire","1 cucharada de salsa de soya o tamari para versión sin gluten"),("Nueces pecanas especiadas en freidora de aire","¼ de cucharadita de chile en polvo"),("Nueces pecanas especiadas en freidora de aire","⅛ de cucharadita de pimienta de cayena"),("Nueces pecanas especiadas en freidora de aire","1.5 tazas de mitades de nuez pecana")],
["Determine qué sabor va a preparar, el dulce o el especiado. Luego combine los primeros cuatro ingredientes de ese sabor en un tazón pequeño y reserve. Coloque las nueces pecanas en otro tazón y vierta la mezcla encima. Mezcle bien para asegurarse de que cada mitad de nuez pecana quede cubierta.","Forre una bandeja pequeña para hornear con papel pergamino y reserve. Luego coloque con una cuchara las nueces pecanas cubiertas en la canasta de la freidora de aire, pero no las vierta de golpe. Cocine en la freidora de aire a 350 grados F de 3 a 5 minutos, mezclando o sacudiendo la canasta a la mitad del tiempo. Vigile con cuidado para evitar que se quemen. Se cocinan rápido.","Pase las nueces pecanas a la bandeja forrada con papel pergamino en una sola capa para que se enfríen. Haga todo lo posible por no devorarlas tibias, ya que se endurecerán y quedarán crujientes al enfriarse, que es cuando saben mejor. ¡Disfrute! ;)"],
["Distribuya las nueces pecanas en una sola capa después de cocinarlas en la freidora de aire hasta que se enfríen. Haga todo lo posible por no comerlas tibias (aunque siguen siendo deliciosas tibias). Este tiempo de enfriamiento les permitirá endurecerse y evitará que se peguen entre sí. Se enfrían rápidamente y estarán listas para comer en aprox. 10-15 minutos. Las sobras se conservan a temperatura ambiente en un recipiente sellado o frasco de 1 a 2 semanas. La información nutricional anterior representa 1 porción de las nueces pecanas dulces confitadas. Las nueces pecanas especiadas son un poco más ligeras, con 182 calorías y 3 gramos de azúcar por porción."],[]))
X.append(r(9693255,"Waffles veganos de chocolate","Prepare estos waffles veganos de chocolate de 5 ingredientes: ricos, esponjosos y completamente deliciosos.","6 waffles","1 porción",
["120 gramos de harina integral de trigo, aprox. 1 taza","3 cucharadas de cacao en polvo","2 cucharaditas de polvo para hornear","1 taza de leche de soya o la leche no láctea de su elección","1 cucharada de extracto puro de vainilla"],
["Precaliente la wafflera a fuego medio-alto, o según las instrucciones de su fabricante.","Agregue la harina, el cacao en polvo y el polvo para hornear a un tazón grande para mezclar y bata hasta combinar. Luego agregue la leche y la vainilla y revuelva hasta que no queden partes con harina, sin mezclar de más.","Vierta la masa con un cucharón en la wafflera precalentada y cocine según las instrucciones del fabricante, aprox. 4-6 minutos, o hasta alcanzar el punto deseado."],
["Pese la harina para obtener los mejores resultados. Si la toma con la taza directamente de la bolsa, puede terminar con demasiada y necesitar más líquido para que la masa tenga la consistencia correcta.","Pese la harina y el polvo para obtener los mejores resultados. Si los toma con la taza directamente de la bolsa, puede terminar con demasiada cantidad y necesitar más líquido para que la masa tenga la consistencia correcta.","Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y use un cuchillo para nivelar el exceso.","Asegúrese de que su wafflera esté CALIENTE antes de agregar la masa, para evitar que se pegue.","No levante la tapa demasiado pronto o los waffles pueden romperse. En su lugar, levante la tapa lenta y cuidadosamente para revisar si se pegan.","Las tandas siguientes de waffles se cocinan un poco más rápido que la primera, así que vigílelas de cerca.","Los waffles sobrantes se conservan en el refrigerador de 3 a 4 días o congelados hasta por 3 meses."],[]))
X.append(r(9702522,"Waffles de leche de coco [sin aceite]","Los waffles de leche de coco son CRUJIENTES por fuera, pero suaves y esponjosos por dentro.","10 waffles","1 porción",
["270 gramos de harina integral de trigo, aprox. 2 tazas, tomadas con cuchara y niveladas","2 cucharaditas de polvo para hornear","400 ml de leche de coco sin azúcar Thai Kitchen, aprox. 1 lata de 13.5 onzas","⅓ de taza de plátano (banana) machacado, aprox. 1 plátano muy pequeño o la mitad de uno grande","1 cucharadita de extracto puro de vainilla","2-4 cucharadas de agua, si es necesario",("Coberturas opcionales","mermelada de arándanos y chía"),("Coberturas opcionales","fruta fresca"),("Coberturas opcionales","jarabe de arce")],
["Precaliente la wafflera a fuego medio-alto.","En un tazón grande para mezclar, bata juntos la harina y el polvo para hornear. Luego agregue la leche de coco, el plátano y la vainilla y mezcle hasta que apenas se combinen y no queden partes con harina, pero sin mezclar de más. Unos cuantos grumos están perfectamente bien.NOTA: Si la masa se ve demasiado espesa (debe poder verterse, similar a la masa de panqueques), agregue el agua opcional y revuelva todo rápidamente de nuevo.","Cocine los waffles según las instrucciones del fabricante, aprox. 5-6 minutos por cada tanda. Cocine más tiempo para waffles más crujientes y menos para waffles más suaves.","Sirva con mermelada de arándanos y chía, jarabe de arce o fruta fresca."],
["Use leche de coco enlatada (entera O light), pero no la sustituya por otra leche vegetal. El contenido de grasa es necesario para waffles más crujientes, especialmente porque esta receta no lleva aceite ni mantequilla. Pese la harina para obtener los mejores resultados. Si toma la harina con la taza directamente de la bolsa, probablemente terminará con demasiada y necesitará más líquido para que la masa quede en su punto. Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y use un cuchillo para nivelar el exceso. Use un plátano muy maduro, con manchas marrones, para un dulzor natural y el mejor sabor. Asegúrese de que su wafflera esté CALIENTE antes de agregar la masa, para evitar que se pegue. No levante la tapa demasiado pronto o los waffles pueden romperse. Espere al menos el número mínimo de minutos indicado en las instrucciones del fabricante antes de revisar el punto de cocción. Las tandas siguientes de waffles se cocinan un poco más rápido que la primera, así que vigílelas de cerca."],[]))
X.append(r(9702792,"Arroz de coco con basmati integral en Instant Pot","El arroz de coco en Instant Pot es una excelente guarnición para cualquier comida. Se prepara rápidamente, con ingredientes saludables y ¡mucho sabor!","6 porciones","1 porción",
["2 tazas de arroz basmati integral","1 lata de 400 ml de leche de coco light","1 taza de agua","½ cucharadita de sal marina"],
["Agregue el arroz a un colador y enjuague bien con agua fría.","Coloque todos los ingredientes en su Instant Pot y mezcle bien. Asegúrese de que el arroz esté cubierto por los líquidos para que se cocine de manera uniforme. Luego cierre la tapa y asegúrese de que la válvula de liberación esté en la posición de sellado. Programe a alta presión durante 22 minutos. (Tardará unos 10 minutos en acumular presión antes de comenzar la cuenta regresiva.)","Deje que la presión se libere de forma natural durante 10 minutos y luego libere la presión restante con la válvula de liberación.","¡Esponje con un tenedor y disfrute!"],
["Enjuague bien el arroz antes de cocinarlo para eliminar el almidón y evitar que el arroz se pegue y se apelmace. Agite la lata de leche de coco antes de abrirla y verterla en la olla. El agua y el contenido de coco se separan al reposar, así que agítela bien. Me gusta usar leche de coco LIGHT para mantener más bajo el contenido de grasa y calorías, pero si desea un sabor a coco y una riqueza aún mayores, elija la versión entera. Asegúrese de revolver muy bien el arroz después de agregar los líquidos al Instant Pot. No queremos ningún grano de arroz por encima de los líquidos, o esas piezas no se cocinarán bien. Para más sabor, saltee ⅓ de taza de cebolla picada finamente antes de agregar los demás ingredientes y cocinar a presión. Una vez cocido, también puede exprimir un poco de jugo de limón fresco sobre el arroz y mezclar bien antes de servir."],[]))
X.append(r(9706219,"Zoodles estilo burrito","¡Disfrute de una versión saludable de un clásico con zoodles estilo burrito!","4 porciones","1 porción",
["3 calabacines (zucchini) medianos","1 taza de tomates cherry (o uva) cortados por la mitad","½ taza de granos de maíz","1 lata de 15 onzas de frijoles negros, escurridos + enjuagados","2 cucharadas de jugo de limón, aprox. 1 limón grande","1 cucharadita de pimentón ahumado","1 cucharadita de chile en polvo","½ cucharadita de cebolla en polvo","½ cucharadita de ajo en polvo","sal + pimienta al gusto",("Coberturas opcionales","cilantro fresco"),("Coberturas opcionales","crema fresca"),("Coberturas opcionales","rodajas de aguacate"),("Coberturas opcionales","gajos de limón")],
["Comience convirtiendo los calabacines en fideos con un espiralizador, si no usa zoodles empaquetados de la tienda. Coloque los zoodles en un colador grande dentro de un tazón grande o en el fregadero de la cocina y espolvoréelos generosamente con sal. Esto marchitará el calabacín y mejorará su sabor. Reserve de 10 a 15 minutos mientras prepara los demás ingredientes.","Luego, prepare las coberturas y/o salsas que desee usar.","A continuación, caliente los frijoles con el jugo de limón y las especias durante unos minutos para que absorban los sabores y apague el fuego.","Opcionalmente, puede calentar los zoodles; sin embargo, no es necesario cocinarlos.","Sirva los zoodles estilo burrito en tazones poco profundos y cúbralos con los frijoles calientes y las demás coberturas. Disfrute."],
["Prepare las coberturas y convierta el calabacín en fideos ANTES de calentar los frijoles.","Para facilitar el espiralizado, use calabacines delgados, largos y rectos. O puede comprar zoodles ya espiralizados y empaquetados en su supermercado para ahorrar tiempo.","NO cocine de más los zoodles. Puede servirlos crudos y fríos, o solo ligeramente calentados. Calentarlos demasiado tiempo los hará aguados y demasiado blandos."],[]))
save(6,X)
